            ->test(AuditReports::class)
            ->call('setSchedule', 'https://github.com/acme/app/', 'weekly');

        $this->assertDatabaseHas('audit_schedules', [
            'user_id' => $user->id,
            'repo_url' => 'https://github.com/acme/app',
            'frequency' => 'weekly',
